"""

STYLE_DEFAULT = {"changes", "grid", "header-filename", "numbers", "snip"}
STYLE_FULL = {"changes", "grid", "header-filename", "header-filesize", "rule", "numbers", "snip"}
STYLE_NAMES = {
    "default", "auto", "full", "plain", "changes", "header", "header-filename",
