    italic_text: str = "never"
    decorations: str = "auto"
    decorations_explicit: bool = False
    force_colorization: bool = False
    paging: str = "auto"
    pager: Optional[str] = None
    map_syntax: List[str] = field(default_factory=list)
    ignored_suffix: List[str] = field(default_factory=list)
    theme: Optional[str] = None
    theme_light: Optional[str] = None
    theme_dark: Optional[str] = None
    squeeze_blank: bool = False
    squeeze_limit: int = 1
    squeeze_limit_explicit: bool = False
    strip_ansi: str = "never"
