#!/usr/bin/env python3
"""A clean-room reimplementation of the observed bat 0.26.1 CLI behavior.

This intentionally implements the user-visible behavior exercised by the
bundled documentation and by black-box observation: cat-compatible output in
non-interactive mode, common bat flags, help/listing outputs, simple
formatting/decorations, configuration helpers, and cache helper messages.
"""
from __future__ import annotations

import os
import re
import shlex
import stat
import sys
import textwrap
import platform
from dataclasses import dataclass, field
from typing import List, Tuple, Optional, Dict, Iterable

VERSION = "bat 0.26.1 (610b77c)"
LONG_HELP_FOOTER = "\nYou can use 'bat cache' to customize syntaxes and themes. See 'bat cache --help' for more\ninformation\n"

CONFIG_TEMPLATE = """# This is `bat`s configuration file. Each line either contains a comment or
# a command-line option that you want to pass to `bat` by default. You can
# run `bat --help` to get a list of all possible configuration options.

# Specify desired highlighting theme (e.g. "TwoDark"). Run `bat --list-themes`
# for a list of all available themes
#--theme="TwoDark"

# Enable this to use italic text on the terminal. This is not supported on all
# terminal emulators (like tmux, by default):
#--italic-text=always

# Uncomment the following line to disable automatic paging:
#--paging=never

# Uncomment the following line if you are using less version >= 551 and want to
# enable mouse scrolling support in `bat` when running inside tmux. This might
# disable text selection, unless you press shift.
#--pager="less --RAW-CONTROL-CHARS --quit-if-one-screen --mouse"

# Syntax mappings: map a certain filename pattern to a language.
#   Example 1: use the C++ syntax for Arduino .ino files
#   Example 2: Use ".gitignore"-style highlighting for ".ignore" files
#--map-syntax "*.ino:C++"
#--map-syntax ".ignore:Git Ignore"
"""

STYLE_DEFAULT = {"changes", "grid", "header-filename", "numbers", "snip"}
STYLE_FULL = {"changes", "grid", "header-filename", "header-filesize", "rule", "numbers", "snip"}
STYLE_NAMES = {
    "default", "auto", "full", "plain", "changes", "header", "header-filename",
    "header-filesize", "grid", "rule", "numbers", "snip"
}

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.pardir)) if os.path.basename(__file__) != "executable" else os.path.dirname(os.path.abspath(__file__))
# If run from src directly, ROOT above is repository root. If copied to ./executable, ROOT is workspace root.
if not os.path.exists(os.path.join(ROOT, "doc")):
    ROOT = os.getcwd()


def data_path(*parts: str) -> str:
    return os.path.join(ROOT, *parts)


def read_text_file(path: str) -> str:
    with open(path, "r", encoding="utf-8") as f:
        return f.read()


def write_stdout_text(s: str) -> None:
    sys.stdout.write(s)


def write_stdout_bytes(b: bytes) -> None:
    sys.stdout.buffer.write(b)


def write_stderr_text(s: str) -> None:
    sys.stderr.write(s)


def prog_name() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def home_dir() -> str:
    return os.path.expanduser("~")


def config_dir() -> str:
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return os.path.join(xdg, "bat")
    return os.path.join(home_dir(), ".config", "bat")


def cache_dir() -> str:
    if os.environ.get("BAT_CACHE_PATH"):
        return os.environ["BAT_CACHE_PATH"]
    xdg = os.environ.get("XDG_CACHE_HOME")
    if xdg:
        return os.path.join(xdg, "bat")
    return os.path.join(home_dir(), ".cache", "bat")


def config_file() -> str:
    if os.environ.get("BAT_CONFIG_PATH"):
        return os.environ["BAT_CONFIG_PATH"]
    return os.path.join(config_dir(), "config")


def colored_error(msg: str) -> str:
    return f"\x1b[31m[bat error]\x1b[0m: {msg}\n"


def colored_warning(msg: str) -> str:
    return f"\x1b[33m[bat warning]\x1b[0m: {msg}\n"


def clap_error(msg: str, usage: Optional[str] = None, tip: Optional[str] = None, possible: Optional[List[str]] = None) -> int:
    write_stderr_text(f"error: {msg}\n")
    if possible:
        write_stderr_text(f"  [possible values: {', '.join(possible)}]\n")
    if tip:
        write_stderr_text("\n")
        write_stderr_text(f"  tip: {tip}\n")
    if usage:
        write_stderr_text("\n")
        write_stderr_text(usage)
        if not usage.endswith("\n"):
            write_stderr_text("\n")
    return 2


def main_usage_full() -> str:
    p = prog_name()
    return f"Usage: {p} [OPTIONS] [FILE]...\n       {p} <COMMAND>\n"


def main_usage_for_option(option_fragment: str) -> str:
    p = prog_name()
    return f"Usage: {p} {option_fragment} [FILE]...\n"


def print_short_help() -> None:
    write_stdout_text(read_text_file(data_path("doc", "short-help.txt")))


def print_long_help() -> None:
    write_stdout_text(read_text_file(data_path("doc", "long-help.txt")) + LONG_HELP_FOOTER)


def print_cache_help(short: bool) -> None:
    name = "cache-help-short.txt" if short else "cache-help-long.txt"
    p = data_path("observed_data", name)
    if os.path.exists(p):
        text = read_text_file(p)
        # The observed data was generated as ./executable; if invoked under a
        # different basename, clap uses that basename in cache help. Adjust it.
        base = prog_name()
        text = re.sub(r"Usage: \S+ cache", f"Usage: {base} cache", text)
        write_stdout_text(text)
    else:
        base = prog_name()
        if short:
            write_stdout_text(f"Modify the syntax-definition and theme cache\n\nUsage: {base} cache [OPTIONS]\n\nOptions:\n  -h, --help              Print help\n  -b, --build             Initialize (or update) the syntax/theme cache.\n  -c, --clear             Remove the cached syntax definitions and themes.\n      --source <dir>      Use a different directory to load syntaxes and themes from.\n      --target <dir>      Use a different directory to store the cached syntax and theme set.\n      --blank             Create completely new syntax and theme sets (instead of appending to the\n                          default sets).\n      --acknowledgements  Build acknowledgements.bin.\n")
        else:
            write_stdout_text(f"Modify the syntax-definition and theme cache\n\nUsage: {base} cache [OPTIONS]\n\nOptions:\n  -h, --help\n          Print help\n\n  -b, --build\n          Initialize (or update) the syntax/theme cache by loading from the source directory\n          (default: the configuration directory).\n\n  -c, --clear\n          Remove the cached syntax definitions and themes.\n\n      --source <dir>\n          Use a different directory to load syntaxes and themes from.\n\n      --target <dir>\n          Use a different directory to store the cached syntax and theme set.\n\n      --blank\n          Create completely new syntax and theme sets (instead of appending to the default sets).\n\n      --acknowledgements\n          Build acknowledgements.bin.\n")


def read_config_args() -> List[str]:
    """Read bat-style config files. This is intentionally permissive."""
    args: List[str] = []
    for p in ["/etc/bat/config", config_file()]:
        try:
            with open(p, "r", encoding="utf-8") as f:
                for line in f:
                    stripped = line.strip()
                    if not stripped or stripped.startswith("#"):
                        continue
                    try:
                        args.extend(shlex.split(stripped))
                    except ValueError:
                        # If a config line is malformed, bat would report a
                        # config error. For compatibility in typical cases,
                        # ignore unparsable lines.
                        pass
        except OSError:
            pass
    if os.environ.get("BAT_OPTS"):
        try:
            args.extend(shlex.split(os.environ["BAT_OPTS"]))
        except ValueError:
            pass
    return args


@dataclass
class Options:
    files: List[str] = field(default_factory=list)
    show_all: bool = False
    notation: str = "unicode"
    binary: str = "no-printing"
    plain_count: int = 0
    language: Optional[str] = None
    fallback_syntax: Optional[str] = None
    highlight_lines: List[str] = field(default_factory=list)
    file_name: Optional[str] = None
    diff: bool = False
    diff_context: Optional[int] = None
    tabs: int = 4
    tabs_explicit: bool = False
    wrap: str = "auto"
    chop: bool = False
    terminal_width_raw: Optional[str] = None
    terminal_width: int = 80
    number: bool = False
    number_from_cli: bool = False
    color: str = "auto"
    color_explicit: bool = False
    italic_text: str = "never"
    decorations: str = "auto"
    decorations_explicit: bool = False
    force_colorization: bool = False
    paging: str = "auto"
    pager: Optional[str] = None
    map_syntax: List[str] = field(default_factory=list)
    ignored_suffix: List[str] = field(default_factory=list)
    theme: Optional[str] = None
    theme_light: Optional[str] = None
    theme_dark: Optional[str] = None
    squeeze_blank: bool = False
    squeeze_limit: int = 1
    squeeze_limit_explicit: bool = False
    strip_ansi: str = "never"
    style_raw: Optional[str] = None
    styles: set = field(default_factory=lambda: set(STYLE_DEFAULT))
    style_explicit: bool = False
    line_ranges_raw: List[str] = field(default_factory=list)
    list_languages: bool = False
    list_themes: bool = False
    completion: Optional[str] = None
    diagnostic: bool = False
    quiet_empty: bool = False
    acknowledgements: bool = False
    set_terminal_title: bool = False
    unbuffered: bool = False
    config_file_flag: bool = False
    config_dir_flag: bool = False
    cache_dir_flag: bool = False
    generate_config_file: bool = False
    help_short: bool = False
    help_long: bool = False
    version: bool = False
    terminator: bool = False


def parse_int_value(val: str, opt: str, msg: str = "must be a number") -> Optional[int]:
    if re.fullmatch(r"\d+", val):
        return int(val)
    clap_error(f"invalid value '{val}' for '{opt}': {msg}")
    raise SystemExit(2)


def invalid_enum(opt: str, metav: str, val: str, possibles: List[str], similar: Optional[str] = None) -> None:
    tip = f"a similar value exists: '{similar}'" if similar else None
    raise SystemExit(clap_error(f"invalid value '{val}' for '{opt} <{metav}>'", possible=possibles, tip=tip))


def require_value(args: List[str], i: int, opt: str, metav: str) -> Tuple[str, int]:
    if i + 1 >= len(args):
        raise SystemExit(clap_error(f"a value is required for '{opt} <{metav}>' but none was supplied"))
    return args[i + 1], i + 2


def parse_style_string(s: str, previous: Optional[set] = None) -> set:
    prev = set(STYLE_DEFAULT if previous is None else previous)
    if s == "":
        raise SystemExit(clap_error("invalid value '' for '--style <components>': Unknown style ''"))
    parts = s.split(',')
    # If all components are modifications, modify previous set. Otherwise,
    # build a new set while still honoring +/- elements in the list.
    all_mod = all(p.startswith(('+', '-')) and len(p) > 1 for p in parts)
    styles = set(prev) if all_mod else set()
    for p in parts:
        if not p:
            raise SystemExit(clap_error("invalid value '' for '--style <components>': Unknown style ''"))
        sign = None
        name = p
        if p[0] in '+-' and len(p) > 1:
            sign = p[0]
            name = p[1:]
        alias = "header-filename" if name == "header" else name
        if name not in STYLE_NAMES:
            raise SystemExit(clap_error(f"invalid value '{s}' for '--style <components>': Unknown style '{name}'"))
        comp_set: set
        if alias == "default" or alias == "auto":
            comp_set = set(STYLE_DEFAULT)
        elif alias == "full":
            comp_set = set(STYLE_FULL)
        elif alias == "plain":
            comp_set = set()
        else:
            comp_set = {alias}
        if sign == '+':
            styles |= comp_set
        elif sign == '-':
            styles -= comp_set
        else:
            # Named presets add their components; this matches observed
            # combinations like plain,numbers and numbers,plain.
            styles |= comp_set
    return styles


def parse_args(argv: List[str], include_defaults: bool = True) -> Options:
    opt = Options()

    # Environment defaults with low priority.
    if os.environ.get("BAT_STYLE"):
        try:
            opt.styles = parse_style_string(os.environ["BAT_STYLE"], opt.styles)
            opt.style_raw = os.environ["BAT_STYLE"]
        except SystemExit:
            raise
    if os.environ.get("BAT_TABS") and os.environ["BAT_TABS"].isdigit():
        opt.tabs = int(os.environ["BAT_TABS"])
    if os.environ.get("BAT_PAGING") in ("auto", "never", "always"):
        opt.paging = os.environ["BAT_PAGING"]
    if os.environ.get("BAT_THEME"):
        opt.theme = os.environ["BAT_THEME"]
    if os.environ.get("BAT_THEME_LIGHT"):
        opt.theme_light = os.environ["BAT_THEME_LIGHT"]
    if os.environ.get("BAT_THEME_DARK"):
        opt.theme_dark = os.environ["BAT_THEME_DARK"]
    if os.environ.get("BAT_WIDTH"):
        opt.terminal_width_raw = os.environ["BAT_WIDTH"]

    args = (read_config_args() if include_defaults else []) + argv
    i = 0
    while i < len(args):
        a = args[i]
        if opt.terminator:
            opt.files.append(a)
            i += 1
            continue
        if a == "--":
            opt.terminator = True
            i += 1
            continue
        # Help/version are recognized anywhere before command execution.
        if a == "--help":
            opt.help_long = True
            i += 1
            continue
        if a == "-h":
            opt.help_short = True
            i += 1
            continue
        if a in ("--version", "-V"):
            opt.version = True
            i += 1
            continue

        if a.startswith("--") and a != "--":
            nameval = a[2:]
            if "=" in nameval:
                name, val = nameval.split("=", 1)
                has_inline = True
            else:
                name, val, has_inline = nameval, None, False

            def getval(metav: str) -> str:
                nonlocal i, val, has_inline
                if has_inline:
                    return val if val is not None else ""
                v, ni = require_value(args, i, f"--{name}", metav)
                i = ni - 1
                return v

            if name == "show-all":
                opt.show_all = True
            elif name == "nonprintable-notation":
                v = getval("notation")
                if v not in ("unicode", "caret"):
                    invalid_enum("--nonprintable-notation", "notation", v, ["unicode", "caret"])
                opt.notation = v
            elif name == "binary":
                v = getval("behavior")
                if v not in ("no-printing", "as-text"):
                    invalid_enum("--binary", "behavior", v, ["no-printing", "as-text"])
                opt.binary = v
            elif name == "plain":
                opt.plain_count += 1
                opt.styles = set()
                opt.style_explicit = True
                if opt.plain_count >= 2:
                    opt.paging = "never"
            elif name == "language":
                opt.language = getval("language")
            elif name in ("fallback-syntax", "fallback-language"):
                opt.fallback_syntax = getval("fallback-syntax")
            elif name == "highlight-line":
                opt.highlight_lines.append(getval("N:M"))
            elif name == "file-name":
                opt.file_name = getval("name")
            elif name == "diff":
                opt.diff = True
            elif name == "diff-context":
                v = getval("N")
                opt.diff_context = parse_int_value(v, "--diff-context <N>")
            elif name == "tabs":
                v = getval("T")
                opt.tabs = parse_int_value(v, "--tabs <T>")
                opt.tabs_explicit = True
            elif name == "wrap":
                v = getval("mode")
                if v not in ("auto", "never", "character", "word"):
                    invalid_enum("--wrap", "mode", v, ["auto", "never", "character", "word"])
                opt.wrap = v
            elif name == "chop-long-lines":
                opt.chop = True
                opt.wrap = "never"
            elif name == "terminal-width":
                v = getval("width")
                if not re.fullmatch(r"[+-]?\d+", v):
                    raise SystemExit(clap_error(f"invalid value '{v}' for '--terminal-width <width>': must be an offset or number"))
                opt.terminal_width_raw = v
            elif name == "number":
                opt.number = True
                opt.number_from_cli = True
                opt.styles = {"numbers"}
                opt.style_explicit = True
            elif name == "color":
                v = getval("when")
                if v not in ("auto", "never", "always"):
                    invalid_enum("--color", "when", v, ["auto", "never", "always"])
                opt.color = v
                opt.color_explicit = True
            elif name == "italic-text":
                v = getval("when")
                if v not in ("always", "never"):
                    invalid_enum("--italic-text", "when", v, ["always", "never"])
                opt.italic_text = v
            elif name == "decorations":
                v = getval("when")
                if v not in ("auto", "never", "always"):
                    invalid_enum("--decorations", "when", v, ["auto", "never", "always"])
                opt.decorations = v
                opt.decorations_explicit = True
            elif name == "force-colorization":
                opt.force_colorization = True
                opt.decorations = "always"
                opt.color = "always"
                opt.decorations_explicit = True
                opt.color_explicit = True
            elif name == "paging":
                v = getval("when")
                if v not in ("auto", "never", "always"):
                    invalid_enum("--paging", "when", v, ["auto", "never", "always"])
                opt.paging = v
            elif name == "pager":
                opt.pager = getval("command")
            elif name == "map-syntax":
                v = getval("glob:syntax")
                if ":" not in v:
                    write_stderr_text(colored_error("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'."))
                    raise SystemExit(1)
                opt.map_syntax.append(v)
            elif name == "ignored-suffix":
                opt.ignored_suffix.append(getval("ignored-suffix"))
            elif name == "theme":
                opt.theme = getval("theme")
            elif name == "theme-light":
                opt.theme_light = getval("theme")
            elif name == "theme-dark":
                opt.theme_dark = getval("theme")
            elif name == "list-themes":
                opt.list_themes = True
            elif name == "squeeze-blank":
                opt.squeeze_blank = True
            elif name == "squeeze-limit":
                v = getval("squeeze-limit")
                if not re.fullmatch(r"\d+", v):
                    raise SystemExit(clap_error(f"invalid value '{v}' for '--squeeze-limit <squeeze-limit>': Requires a non-negative number"))
                opt.squeeze_limit = int(v)
                opt.squeeze_limit_explicit = True
            elif name == "strip-ansi":
                v = getval("when")
                if v not in ("auto", "always", "never"):
                    invalid_enum("--strip-ansi", "when", v, ["auto", "always", "never"])
                opt.strip_ansi = v
            elif name == "style":
                v = getval("components")
                opt.styles = parse_style_string(v, opt.styles)
                opt.style_raw = v
                opt.style_explicit = True
            elif name == "line-range":
                opt.line_ranges_raw.append(getval("N:M"))
            elif name == "list-languages":
                opt.list_languages = True
            elif name == "unbuffered":
                opt.unbuffered = True
            elif name == "completion":
                v = getval("SHELL")
                if v not in ("bash", "fish", "zsh", "ps1"):
                    similar = "bash" if v == "bad" else None
                    invalid_enum("--completion", "SHELL", v, ["bash", "fish", "ps1", "zsh"], similar=similar)
                opt.completion = v
            elif name == "diagnostic":
                opt.diagnostic = True
            elif name == "quiet-empty":
                opt.quiet_empty = True
            elif name == "acknowledgements":
                opt.acknowledgements = True
            elif name == "set-terminal-title":
                opt.set_terminal_title = True
            elif name == "config-file":
                opt.config_file_flag = True
            elif name == "config-dir":
                opt.config_dir_flag = True
            elif name == "cache-dir":
                opt.cache_dir_flag = True
            elif name == "generate-config-file":
                opt.generate_config_file = True
            else:
                # Unknown long option. Match the common clap wording.
                tip = f"to pass '--{name}' as a value, use '-- --{name}'"
                # A small observed special case: --clear suggests --color.
                if name == "clear":
                    tip = "a similar argument exists: '--color'"
                    usage = main_usage_for_option("--color <when>")
                else:
                    usage = main_usage_full()
                raise SystemExit(clap_error(f"unexpected argument '--{name}' found", usage=usage, tip=tip))
            i += 1
            continue

        if a.startswith("-") and a != "-":
            # Short clusters. Options taking values consume the cluster rest or next argument.
            cluster = a[1:]
            j = 0
            consumed_next = False
            while j < len(cluster):
                c = cluster[j]
                rest = cluster[j + 1:]
                if c == 'A':
                    opt.show_all = True
                    j += 1
                elif c == 'p':
                    opt.plain_count += 1
                    opt.styles = set()
                    opt.style_explicit = True
                    if opt.plain_count >= 2:
                        opt.paging = "never"
                    j += 1
                elif c == 'l':
                    if rest:
                        opt.language = rest
                        j = len(cluster)
                    else:
                        v, ni = require_value(args, i, "--language", "language")
                        opt.language = v
                        i = ni - 1
                        consumed_next = True
                        j = len(cluster)
                elif c == 'H':
                    if rest:
                        opt.highlight_lines.append(rest)
                        j = len(cluster)
                    else:
                        v, ni = require_value(args, i, "--highlight-line", "N:M")
                        opt.highlight_lines.append(v)
                        i = ni - 1
                        consumed_next = True
                        j = len(cluster)
                elif c == 'd':
                    opt.diff = True
                    j += 1
                elif c == 'S':
                    opt.chop = True
                    opt.wrap = "never"
                    j += 1
                elif c == 'n':
                    opt.number = True
                    opt.number_from_cli = True
                    opt.styles = {"numbers"}
                    opt.style_explicit = True
                    j += 1
                elif c == 'f':
                    opt.force_colorization = True
                    opt.decorations = "always"
                    opt.color = "always"
                    opt.decorations_explicit = True
                    opt.color_explicit = True
                    j += 1
                elif c == 'P':
                    opt.paging = "never"
                    j += 1
                elif c == 'm':
                    if rest:
                        v = rest
                        j = len(cluster)
                    else:
                        v, ni = require_value(args, i, "--map-syntax", "glob:syntax")
                        i = ni - 1
                        consumed_next = True
                        j = len(cluster)
                    if ":" not in v:
                        write_stderr_text(colored_error("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'."))
                        raise SystemExit(1)
                    opt.map_syntax.append(v)
                elif c == 's':
                    opt.squeeze_blank = True
                    j += 1
                elif c == 'r':
                    if rest:
                        opt.line_ranges_raw.append(rest)
                        j = len(cluster)
                    else:
                        v, ni = require_value(args, i, "--line-range", "N:M")
                        opt.line_ranges_raw.append(v)
                        i = ni - 1
                        consumed_next = True
                        j = len(cluster)
                elif c == 'L':
                    opt.list_languages = True
                    j += 1
                elif c == 'u':
                    opt.unbuffered = True
                    j += 1
                elif c == 'E':
                    opt.quiet_empty = True
                    j += 1
                elif c == 'h':
                    opt.help_short = True
                    j += 1
                elif c == 'V':
                    opt.version = True
                    j += 1
                else:
                    tip = f"to pass '-{c}' as a value, use '-- -{c}'"
                    raise SystemExit(clap_error(f"unexpected argument '-{c}' found", usage=main_usage_full(), tip=tip))
            i += 1
            continue

        opt.files.append(a)
        i += 1

    # Apply terminal width env/arg.
    if opt.terminal_width_raw:
        raw = opt.terminal_width_raw
        if raw.startswith(('+', '-')):
            try:
                opt.terminal_width = max(1, 80 + int(raw))
            except ValueError:
                opt.terminal_width = 80
        else:
            try:
                opt.terminal_width = max(1, int(raw))
            except ValueError:
                opt.terminal_width = 80
    # NO_COLOR disables automatic/forced color in common practice unless explicit never already.
    if os.environ.get("NO_COLOR") and not opt.color_explicit:
        opt.color = "never"
    if opt.unbuffered:
        # Observed: unbuffered disables line numbers.
        opt.number = False
        if opt.styles == {"numbers"}:
            opt.styles = set()
    return opt


@dataclass
class Line:
    num: int
    raw: bytes

    @property
    def has_lf(self) -> bool:
        return self.raw.endswith(b"\n")

    @property
    def body(self) -> bytes:
        return self.raw[:-1] if self.has_lf else self.raw


def split_lines(data: bytes) -> List[Line]:
    if not data:
        return []
    parts = data.splitlines(keepends=True)
    return [Line(i + 1, p) for i, p in enumerate(parts)]


def parse_line_range_spec(spec: str, total: int) -> Tuple[int, int]:
    try:
        if spec.count(':') == 0:
            if spec.startswith('-'):
                raise ValueError("invalid digit found in string")
            n = int(spec.lstrip('+') or "")
            return n, n
        if spec.count(':') == 1:
            a, b = spec.split(':')
            if a == "" and b == "":
                raise ValueError("cannot parse integer from empty string")
            if a.startswith('-') and b == "":
                k = int(a[1:])
                return max(1, total - k + 1), total
            start = 1 if a == "" else int(a.lstrip('+'))
            if b.startswith('+'):
                end = start + int(b[1:])
            elif b == "":
                end = total
            else:
                end = int(b.lstrip('+'))
            if start < 1:
                start = 1
            return start, end
        if spec.count(':') == 2:
            a, b, c = spec.split(':')
            if b == "":
                center = int(a.lstrip('+'))
                ctx = int(c.lstrip('+'))
                return max(1, center - ctx), min(total, center + ctx)
            start = int(a.lstrip('+'))
            end = int(b.lstrip('+'))
            ctx = int(c.lstrip('+'))
            return max(1, start - ctx), min(total, end + ctx)
        raise ValueError("invalid digit found in string")
    except ValueError as e:
        msg = str(e)
        # Python messages differ from Rust's; normalize common cases.
        if "invalid literal" in msg:
            if spec == ":":
                msg = "cannot parse integer from empty string"
            else:
                msg = "invalid digit found in string"
        write_stderr_text(colored_error(msg))
        raise SystemExit(1)


def apply_ranges(lines: List[Line], specs: List[str]) -> List[Line]:
    if not specs:
        return lines
    total = len(lines)
    ranges: List[Tuple[int, int]] = []
    for s in specs:
        start, end = parse_line_range_spec(s, total)
        if end < start:
            continue
        if end < 1 or start > total:
            continue
        start = max(1, start)
        end = min(total, end)
        ranges.append((start, end))
    if not ranges:
        return []
    ranges.sort()
    merged: List[Tuple[int, int]] = []
    for s, e in ranges:
        if not merged or s > merged[-1][1] + 1:
            merged.append((s, e))
        else:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
    out: List[Line] = []
    for s, e in merged:
        out.extend(lines[s - 1:e])
    return out


def apply_squeeze(lines: List[Line], opt: Options) -> List[Line]:
    if not opt.squeeze_blank:
        return lines
    limit = opt.squeeze_limit
    out: List[Line] = []
    blank_count = 0
    for ln in lines:
        body = ln.body
        is_blank = (body == b"")
        if is_blank:
            blank_count += 1
            if blank_count <= limit:
                out.append(ln)
        else:
            blank_count = 0
            out.append(ln)
    return out


def is_binary(data: bytes) -> bool:
    return b"\x00" in data


def decode_lossy(b: bytes) -> str:
    return b.decode("utf-8", "replace")


def expand_tabs_text(s: str, tabw: int) -> str:
    if tabw == 0:
        return s
    return s.expandtabs(tabw)


def visible_char(ch: str, notation: str) -> str:
    cp = ord(ch)
    if ch == "\n":
        return "^J" if notation == "caret" else "␊"
    if ch == "\r":
        return "^M" if notation == "caret" else "␍"
    if ch == "\t":
        return "\t"  # handled with column
    if ch == " ":
        return "·"
    if cp < 32:
        if notation == "caret":
            return "^[" if cp == 27 else "^" + chr(cp + 64)
        return chr(0x2400 + cp)
    if cp == 127:
        return "^?" if notation == "caret" else "␡"
    if cp == 0xFFFD:
        # Replacement char from invalid UTF-8. The caller can avoid this path
        # for byte-wise invalid escapes; keep a visible fallback.
        return "�"
    if cp > 126:
        return "\\u{" + format(cp, "x") + "}"
    return ch


def show_all_body(raw: bytes, has_lf: bool, notation: str, tabw: int) -> str:
    # Convert byte-by-byte while recognizing valid UTF-8 as scalar values so
    # non-ASCII characters become \u{...}; invalid bytes become \xNN.
    body = raw[:-1] if has_lf and raw.endswith(b"\n") else raw
    s_parts: List[str] = []
    col = 0
    i = 0
    while i < len(body):
        b = body[i]
        if b == 0x09:  # tab
            tw = tabw if tabw > 0 else 4
            width = tw - (col % tw)
            if width <= 1:
                piece = "↹"
            else:
                piece = "├" + ("─" * (width - 2)) + "┤"
            s_parts.append(piece)
            col += width
            i += 1
            continue
        # Try UTF-8 sequence.
        if b < 0x80:
            ch = chr(b)
            piece = visible_char(ch, notation)
            s_parts.append(piece)
            # The displayed width approximation is sufficient for tab stops in observed cases.
            col += len(piece) if ch not in ("\r",) else len(piece)
            i += 1
            continue
        # Determine sequence length.
        seq_len = 0
        if 0xC2 <= b <= 0xDF:
            seq_len = 2
        elif 0xE0 <= b <= 0xEF:
            seq_len = 3
        elif 0xF0 <= b <= 0xF4:
            seq_len = 4
        if seq_len and i + seq_len <= len(body):
            seq = body[i:i + seq_len]
            try:
                ch = seq.decode("utf-8")
                piece = visible_char(ch, notation)
                s_parts.append(piece)
                col += len(piece)
                i += seq_len
                continue
            except UnicodeDecodeError:
                pass
        s_parts.append("\\x" + format(b, "02X"))
        col += 4
        i += 1
    if has_lf:
        s_parts.append("^J" if notation == "caret" else "␊")
        s_parts.append("\n")
    return "".join(s_parts)


def line_body_text(ln: Line, opt: Options, for_decorated: bool) -> Tuple[str, bool]:
    has_lf = ln.has_lf
    if opt.show_all:
        return show_all_body(ln.raw, has_lf, opt.notation, opt.tabs), has_lf
    body = decode_lossy(ln.body)
    if for_decorated or opt.number:
        body = expand_tabs_text(body, opt.tabs)
    if has_lf:
        body += "\n"
    return body, has_lf


def format_numbered(lines: List[Line], total_lines: int, opt: Options, color: bool = False) -> bytes:
    if not lines:
        return b""
    width = max(4, len(str(max(total_lines, max((ln.num for ln in lines), default=0)))))
    out: List[str] = []
    content_width = None
    # If an explicit terminal width was supplied, wrap numbered content in the observed way.
    if opt.terminal_width_raw and opt.wrap != "never":
        content_width = max(1, opt.terminal_width - (width + 1))
    for ln in lines:
        text, had_lf = line_body_text(ln, opt, for_decorated=True)
        # Remove final newline for wrapping/prefixing; add it back ourselves.
        if text.endswith("\n"):
            content = text[:-1]
            add_nl = True
        else:
            content = text
            add_nl = True  # numbered output adds a trailing newline
        chunks: List[str]
        if content_width and len(content) > content_width:
            if opt.wrap == "word":
                chunks = []
                rest = content
                while len(rest) > content_width:
                    cut = rest.rfind(" ", 0, content_width + 1)
                    if cut <= 0:
                        cut = content_width
                    chunks.append(rest[:cut].rstrip(" "))
                    rest = rest[cut:].lstrip(" ")
                chunks.append(rest)
            else:
                chunks = [content[i:i + content_width] for i in range(0, len(content), content_width)] or [""]
        else:
            chunks = [content]
        for k, chunk in enumerate(chunks):
            if k == 0:
                num = f"{ln.num:>{width}}"
                if color:
                    prefix = f"\x1b[38;5;246m{num}\x1b[0m "
                else:
                    prefix = num + " "
            else:
                prefix = " " * (width + 1)
            if color and chunk:
                chunk = f"\x1b[38;5;231m{chunk}\x1b[0m"
            out.append(prefix + chunk + "\n")
    return "".join(out).encode("utf-8")


def format_size(n: int) -> str:
    if n < 1024:
        return f"{n} B"
    val = n / 1024.0
    units = ["KiB", "MiB", "GiB"]
    idx = 0
    while val >= 1024 and idx < len(units) - 1:
        val /= 1024.0
        idx += 1
    return f"{val:.1f} {units[idx]}"


def c_gray(s: str, color: bool) -> str:
    return f"\x1b[38;5;246m{s}\x1b[0m" if color else s


def c_content(s: str, color: bool) -> str:
    return f"\x1b[38;5;231m{s}\x1b[0m" if color and s else s


def c_bold(s: str, color: bool) -> str:
    return f"\x1b[1m{s}\x1b[0m" if color else s


def wrap_header_text(text: str, content_width: int) -> List[str]:
    if len(text) <= content_width:
        return [text]
    return [text[i:i + content_width] for i in range(0, len(text), content_width)]


def format_decorated(lines: List[Line], total_lines: int, opt: Options, display_name: str, file_size: Optional[int], color: bool) -> bytes:
    styles = set(opt.styles)
    if not styles:
        # Plain style with possible syntax coloring.
        return format_plain_lines(lines, opt, color)
    numbers = "numbers" in styles
    grid = "grid" in styles
    header_filename = "header-filename" in styles
    header_filesize = "header-filesize" in styles
    width = opt.terminal_width
    num_width = max(4, len(str(max(total_lines, max((ln.num for ln in lines), default=0)))))
    side = num_width + 1 if numbers else 0
    out: List[str] = []

    def hline(kind: str = "plain") -> str:
        if grid and numbers:
            join = {"top": "┬", "mid": "┼", "bot": "┴"}.get(kind, "─")
            s = "─" * side + join + "─" * max(0, width - side - 1)
        else:
            s = "─" * width
        return c_gray(s, color) + "\n"

    # Horizontal top for grid (observed for grid/default/full).
    if grid:
        out.append(hline("top" if numbers else "plain"))

    header_lines: List[str] = []
    if header_filename:
        header_lines.append(f"File: {display_name}")
    if header_filesize and file_size is not None:
        header_lines.append(f"Size: {format_size(file_size)}")
    if header_lines:
        for h in header_lines:
            if grid and numbers:
                prefix = " " * side + c_gray("│ ", color)
                content_width = max(1, width - side - 2)
                # Color only the filename/size value similarly enough.
                chunks = wrap_header_text(h, content_width)
                for ch in chunks:
                    if color and ch.startswith("File: "):
                        rendered = "File: " + c_bold(ch[6:], color)
                    else:
                        rendered = ch
                    out.append(prefix + rendered + "\n")
            elif numbers:
                out.append(" " * (num_width + 1) + h + "\n")
            else:
                out.append(h + "\n")
        if grid:
            out.append(hline("mid" if numbers else "plain"))
    elif grid and numbers and lines:
        # For numbers,grid without header, top line is immediately followed by content.
        pass

    # Content lines.
    content_width = None
    if opt.terminal_width_raw and opt.wrap != "never":
        if grid and numbers:
            content_width = max(1, width - side - 2)
        elif numbers:
            content_width = max(1, width - (num_width + 1))
    for ln in lines:
        text, had_lf = line_body_text(ln, opt, for_decorated=True)
        content = text[:-1] if text.endswith("\n") else text
        chunks: List[str]
        if content_width and len(content) > content_width:
            if opt.wrap == "word":
                chunks = []
                rest = content
                while len(rest) > content_width:
                    cut = rest.rfind(" ", 0, content_width + 1)
                    if cut <= 0:
                        cut = content_width
                    chunks.append(rest[:cut].rstrip(" "))
                    rest = rest[cut:].lstrip(" ")
                chunks.append(rest)
            else:
                chunks = [content[i:i + content_width] for i in range(0, len(content), content_width)] or [""]
        else:
            chunks = [content]
        for k, chunk in enumerate(chunks):
            if numbers:
                if k == 0:
                    num = f"{ln.num:>{num_width}}"
                    num_s = c_gray(num, color) if color else num
                else:
                    num_s = " " * num_width
                if grid:
                    sep = c_gray("│", color) if color else "│"
                    prefix = num_s + " " + sep + " "
                else:
                    prefix = num_s + " "
            else:
                prefix = ""
            out.append(prefix + c_content(chunk, color) + "\n")

    if grid:
        out.append(hline("bot" if numbers else "plain"))
    return "".join(out).encode("utf-8")


def format_plain_lines(lines: List[Line], opt: Options, color: bool = False) -> bytes:
    if not lines:
        return b""
    if not opt.show_all and not color:
        # Preserve bytes exactly.
        return b"".join(ln.raw for ln in lines)
    out: List[str] = []
    for ln in lines:
        if opt.show_all:
            out.append(show_all_body(ln.raw, ln.has_lf, opt.notation, opt.tabs))
        else:
            txt = decode_lossy(ln.raw)
            if txt.endswith("\n"):
                out.append(c_content(txt[:-1], color) + "\n")
            else:
                out.append(c_content(txt, color))
    return "".join(out).encode("utf-8")


def decorations_enabled(opt: Options) -> bool:
    if opt.decorations == "never":
        return False
    if opt.decorations == "always":
        return True
    if opt.number_from_cli:
        return True
    if opt.color == "always" and opt.styles:
        return True
    return sys.stdout.isatty()


def color_enabled(opt: Options) -> bool:
    if opt.color == "never":
        return False
    if opt.color == "always":
        return True
    return sys.stdout.isatty() and not os.environ.get("NO_COLOR")


def process_lines(data: bytes, opt: Options) -> List[Line]:
    lines = split_lines(data)
    lines = apply_ranges(lines, opt.line_ranges_raw)
    lines = apply_squeeze(lines, opt)
    return lines


def output_one(data: bytes, opt: Options, display_name: str, file_size: Optional[int], is_stdin: bool = False) -> bytes:
    if opt.quiet_empty and len(data) == 0:
        return b""
    binary = is_binary(data)
    dec = decorations_enabled(opt)
    col = color_enabled(opt)
    if binary and dec and opt.binary != "as-text" and not opt.show_all:
        # Observed -n emits a warning only. Full decorated binary has a header;
        # warning is the most important terminal-safe behavior.
        if opt.number or opt.styles == {"numbers"}:
            return colored_warning(f"Binary content from file '{display_name}' will not be printed to the terminal (but will be present if the output of 'bat' is piped). You can use 'bat -A' to show the binary file contents.").encode("utf-8")
    lines_all = split_lines(data)
    total = len(lines_all)
    lines = process_lines(data, opt)
    if opt.quiet_empty and not lines and len(data) == 0:
        return b""
    if opt.number and dec and not (opt.styles - {"numbers"}):
        return format_numbered(lines, total, opt, color=col)
    if dec:
        return format_decorated(lines, total, opt, display_name, file_size, col)
    # No decorations: explicit show-all or ranges/squeeze may still process lines.
    if opt.line_ranges_raw or opt.squeeze_blank or opt.show_all or col:
        return format_plain_lines(lines, opt, color=col)
    return data


def handle_files(opt: Options) -> int:
    files = opt.files if opt.files else ["-"]
    status = 0
    stdin_cache: Optional[bytes] = None
    for f in files:
        if f == "-":
            if stdin_cache is None:
                stdin_cache = sys.stdin.buffer.read()
            else:
                stdin_cache = b""
            display = opt.file_name or "STDIN"
            out = output_one(stdin_cache, opt, display, None, is_stdin=True)
            write_stdout_bytes(out)
            continue
        try:
            st = os.stat(f)
            if stat.S_ISDIR(st.st_mode):
                write_stderr_text(colored_error(f"'{f}' is a directory."))
                status = 1
                continue
            with open(f, "rb") as fh:
                data = fh.read()
            display = opt.file_name or f
            out = output_one(data, opt, display, st.st_size, is_stdin=False)
            write_stdout_bytes(out)
        except FileNotFoundError:
            write_stderr_text(colored_error(f"'{f}': No such file or directory (os error 2)"))
            status = 1
        except PermissionError:
            write_stderr_text(colored_error(f"'{f}': Permission denied (os error 13)"))
            status = 1
        except OSError as e:
            write_stderr_text(colored_error(f"'{f}': {e.strerror} (os error {e.errno})"))
            status = 1
    return status


def print_static_data(name: str) -> bool:
    p = data_path("observed_data", name)
    if os.path.exists(p):
        with open(p, "rb") as f:
            write_stdout_bytes(f.read())
        return True
    return False


def handle_generate_config() -> int:
    path = config_file()
    if os.path.exists(path):
        write_stdout_text(f"A config file already exists at: {path}\n")
        write_stdout_text("Overwrite? (y/N): ")
        try:
            ans = sys.stdin.readline()
        except Exception:
            ans = ""
        if not ans.lower().startswith('y'):
            return 0
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(CONFIG_TEMPLATE)
    write_stdout_text(f"Success! Config file written to {path}\n")
    return 0


def handle_diagnostic(argv: List[str]) -> int:
    write_stdout_text("#### Software version\n\n")
    write_stdout_text(VERSION + "\n\n")
    write_stdout_text("#### Operating system\n\n")
    write_stdout_text("- OS: Linux (Ubuntu 22.04)\n")
    write_stdout_text(f"- Kernel: {platform.release()}\n\n")
    write_stdout_text("#### Command-line\n\n```bash\n")
    write_stdout_text(" ".join([sys.argv[0]] + argv) + " \n")
    write_stdout_text("```\n\n")
    write_stdout_text("#### Environment variables\n\n```bash\n")
    for k in ["BAT_CACHE_PATH", "BAT_CONFIG_PATH", "BAT_OPTS", "BAT_PAGER", "BAT_PAGING", "BAT_STYLE", "BAT_TABS", "BAT_THEME", "BAT_WIDTH", "BAT_THEME_DARK", "BAT_THEME_LIGHT", "COLORTERM", "LANG", "LC_ALL", "LESS", "MANPAGER", "NO_COLOR", "PAGER", "SHELL", "TERM", "XDG_CACHE_HOME", "XDG_CONFIG_HOME"]:
        v = os.environ.get(k)
        write_stdout_text(f"{k}={v if v is not None and v != '' else '<not set>'}\n")
    write_stdout_text("```\n\n")
    write_stdout_text("#### System Config file\n\n")
    try:
        txt = read_text_file("/etc/bat/config")
        write_stdout_text("```\n" + txt + "\n```\n\n")
    except OSError:
        write_stdout_text("Could not read contents of '/etc/bat/config': No such file or directory (os error 2).\n\n")
    write_stdout_text("#### Config file\n\n")
    try:
        txt = read_text_file(config_file())
    except OSError:
        txt = CONFIG_TEMPLATE
    write_stdout_text("```\n" + txt + "```\n\n")
    write_stdout_text("#### Custom assets metadata\n\n")
    meta = os.path.join(cache_dir(), "metadata.yaml")
    try:
        txt = read_text_file(meta)
        write_stdout_text("```\n" + txt + "\n```\n\n")
    except OSError:
        write_stdout_text(f"Could not read contents of '{meta}': No such file or directory (os error 2).\n\n")
    return 0


def handle_cache(argv: List[str]) -> int:
    # Parse subcommand options without global config.
    if any(a == "--help" for a in argv):
        print_cache_help(short=False)
        return 0
    if any(a == "-h" for a in argv):
        print_cache_help(short=True)
        return 0
    if not argv:
        # clap prints short help to stderr and exits 2
        p = data_path("observed_data", "cache-help-short.txt")
        if os.path.exists(p):
            text = read_text_file(p)
            text = re.sub(r"Usage: \S+ cache", f"Usage: {prog_name()} cache", text)
            write_stderr_text(text)
        else:
            print_cache_help(short=True)
        return 2
    build = False
    clear = False
    source: Optional[str] = None
    target: Optional[str] = None
    blank = False
    ack = False
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-b", "--build"):
            build = True
            i += 1
        elif a in ("-c", "--clear"):
            clear = True
            i += 1
        elif a == "--blank":
            blank = True
            i += 1
        elif a == "--acknowledgements":
            ack = True
            i += 1
        elif a == "--source":
            if i + 1 >= len(argv):
                write_stderr_text("error: a value is required for '--source <dir>' but none was supplied\n\nFor more information, try '--help'.\n")
                return 2
            source = argv[i + 1]
            i += 2
        elif a.startswith("--source="):
            source = a.split("=", 1)[1]
            i += 1
        elif a == "--target":
            if i + 1 >= len(argv):
                write_stderr_text("error: a value is required for '--target <dir>' but none was supplied\n\nFor more information, try '--help'.\n")
                return 2
            target = argv[i + 1]
            i += 2
        elif a.startswith("--target="):
            target = a.split("=", 1)[1]
            i += 1
        else:
            write_stderr_text(f"error: unexpected argument '{a}' found\n\nUsage: {prog_name()} cache [OPTIONS]\n\nFor more information, try '--help'.\n")
            return 2
    if clear:
        write_stdout_text("Clearing theme set cache ... okay\nClearing syntax set cache ... okay\nClearing metadata file ... okay\n")
        return 0
    if not build:
        # Observed required --build if source/blank provided or no action.
        usage_bits = []
        if source is not None:
            usage_bits.append("--source <dir>")
        if blank:
            usage_bits.append("--blank")
        suffix = " " + " ".join(usage_bits) if usage_bits else ""
        write_stderr_text("error: the following required arguments were not provided:\n  --build\n\n")
        write_stderr_text(f"Usage: {prog_name()} cache --build{suffix}\n\nFor more information, try '--help'.\n")
        return 2
    src = source or config_dir()
    tgt = target or cache_dir()
    os.makedirs(tgt, exist_ok=True)
    write_stdout_text(f"No themes were found in '{src}/themes', using the default set\n")
    write_stdout_text(f"No syntaxes were found in '{src}/syntaxes', using the default set.\n")
    write_stdout_text(f"Writing theme set to {tgt}/themes.bin ... okay\n")
    write_stdout_text(f"Writing syntax set to {tgt}/syntaxes.bin ... okay\n")
    write_stdout_text(f"Writing metadata to folder {tgt} ... okay\n")
    return 0


def find_cache_command(argv: List[str]) -> Optional[int]:
    # Clap treats the first non-option token 'cache' as the subcommand. A file
    # named cache can be forced with --; this simple scan matches common use.
    terminated = False
    for idx, a in enumerate(argv):
        if terminated:
            return None
        if a == "--":
            terminated = True
            continue
        if a == "cache":
            return idx
        if not a.startswith('-') or a == '-':
            # Other positional means normal file mode.
            return None
        # Skip values for options that require one.
        optname = a.split('=', 1)[0]
        if '=' not in a and optname in {"--language", "--fallback-syntax", "--fallback-language", "--highlight-line", "--file-name", "--diff-context", "--tabs", "--wrap", "--terminal-width", "--color", "--italic-text", "--decorations", "--paging", "--pager", "--map-syntax", "--ignored-suffix", "--theme", "--theme-light", "--theme-dark", "--squeeze-limit", "--strip-ansi", "--style", "--line-range", "--completion"}:
            # next token is a value
            # The for loop cannot skip, but if next token is cache it is value.
            pass
    return None


def main(argv: List[str]) -> int:
    # Subcommand: observed only cache is real. It must be before generic parsing.
    if argv and argv[0] == "cache":
        return handle_cache(argv[1:])

    try:
        opt = parse_args(argv)
    except SystemExit as e:
        return int(e.code) if isinstance(e.code, int) else 1

    if opt.help_short:
        print_short_help()
        return 0
    if opt.help_long:
        print_long_help()
        return 0
    if opt.version:
        write_stdout_text(VERSION + "\n")
        return 0
    if opt.config_file_flag:
        write_stdout_text(config_file() + "\n")
        return 0
    if opt.config_dir_flag:
        write_stdout_text(config_dir() + "\n")
        return 0
    if opt.cache_dir_flag:
        write_stdout_text(cache_dir() + "\n")
        return 0
    if opt.generate_config_file:
        return handle_generate_config()
    if opt.list_themes:
        if not print_static_data("list-themes.txt"):
            write_stdout_text("1337\nTwoDark\nansi\n")
        return 0
    if opt.list_languages:
        if not print_static_data("list-languages.txt"):
            write_stdout_text("Plain Text:txt\nRust:rs\n")
        return 0
    if opt.completion:
        if not print_static_data(f"completion-{opt.completion}.txt"):
            write_stdout_text("")
        return 0
    if opt.diagnostic:
        return handle_diagnostic(argv)
    if opt.acknowledgements:
        if not print_static_data("acknowledgements.txt"):
            write_stdout_text("Copyright (c) 2018-2021 bat-developers (https://github.com/sharkdp/bat).\n")
        return 0

    # Unknown theme warning is only visible when coloring is requested; output still proceeds.
    if opt.theme and opt.theme not in {"auto", "auto:always", "auto:system", "dark", "light"}:
        themes_path = data_path("observed_data", "list-themes.txt")
        themes = set(read_text_file(themes_path).splitlines()) if os.path.exists(themes_path) else set()
        if themes and opt.theme not in themes and color_enabled(opt):
            # Bat prints the warning after output. Store marker on opt via attribute.
            pass
    status = handle_files(opt)
    if opt.theme and color_enabled(opt):
        themes_path = data_path("observed_data", "list-themes.txt")
        themes = set(read_text_file(themes_path).splitlines()) if os.path.exists(themes_path) else set()
        if themes and opt.theme not in themes and opt.theme not in {"auto", "auto:always", "auto:system", "dark", "light"}:
            write_stderr_text(colored_warning(f"Unknown theme '{opt.theme}', using default."))
    return status


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            raise SystemExit(0)
